fmt_g implementation:

```rust
pub fn fmt_g(x: f32) -> String {
    if x.is_nan() { return "nan".into(); }
    if x.is_infinite() { return if x < 0.0 { "-inf".into() } else { "inf".into() }; }
    if x == 0.0 {
        return if x.is_sign_negative() { "-0".into() } else { "0".into() };
    }
    // Round to 6 significant digits via scientific formatting.
    let sci = format!("{:.5e}", x); // "d.ddddde±E"
    let epos = sci.find('e').unwrap();
    let mant = &sci[..epos];
    let exp: i32 = sci[epos+1..].parse().unwrap();
    let neg = mant.starts_with('-');
    let digits: String = mant.chars().filter(|c| c.is_ascii_digit()).collect();
    debug_assert_eq!(digits.len(), 6);
    if exp < -4 || exp >= 6 {
        // scientific
        let mut m = String::new();
        if neg { m.push('-'); }
        m.push(digits.as_bytes()[0] as char);
        let frac = digits[1..].trim_end_matches('0');
        if !frac.is_empty() {
            m.push('.');
            m.push_str(frac);
        }
        let sign = if exp < 0 { '-' } else { '+' };
        format!("{}e{}{:02}", m, sign, exp.abs())
    } else if exp >= 0 {
        let int_part = &digits[..(exp as usize + 1)];
        let frac = digits[(exp as usize + 1)..].trim_end_matches('0');
        let mut s = String::new();
        if neg { s.push('-'); }
        s.push_str(int_part);
        if !frac.is_empty() {
            s.push('.');
            s.push_str(frac);
        }
        s
    } else {
        // -4 <= exp < 0
        let zeros = "0".repeat((-exp - 1) as usize);
        let combined = format!("{}{}", zeros, digits);
        let frac = combined.trim_end_matches('0');
        let mut s = String::new();
        if neg { s.push('-'); }
        if frac.is_empty() {
            // can't happen: digits[0] != '0'
            s.push('0');
        } else {
            s.push_str("0.");
            s.push_str(frac);
        }
        s
    }
}
```

