pub mod converter;

pub use converter::ColorConverter;

#[derive(Clone, Copy, Debug, Default)]
pub struct Rgb {
    pub r: f32,
    pub g: f32,
    pub b: f32,
}

impl Rgb {
    pub fn new(r: f32, g: f32, b: f32) -> Self {
        Rgb { r, g, b }
    }
}

#[derive(Clone, Copy, Debug, Default)]
pub struct Hsl {
    pub h: f32,
    pub s: f32,
    pub l: f32,
}

#[derive(Clone, Copy, Debug, Default)]
pub struct Hsv {
    pub h: f32,
    pub s: f32,
    pub v: f32,
}

#[derive(Clone, Copy, Debug, Default)]
pub struct Cmyk {
    pub c: f32,
    pub m: f32,
    pub y: f32,
    pub k: f32,
}

#[derive(Clone, Copy, Debug, Default)]
pub struct Yuv {
    pub y: f32,
    pub u: f32,
    pub v: f32,
}

use super::{Cmyk, Hsl, Hsv, Rgb, Yuv};

pub struct ColorConverter;

fn clamp01(x: f32) -> f32 {
    if x < 0.0 {
        0.0
    } else if x > 1.0 {
        1.0
    } else {
        x
    }
}

// Shared hue computation for HSL/HSV (degrees, [0, 360)).
fn rgb_hue(rgb: Rgb, max: f32, d: f32) -> f32 {
    let mut h = if max == rgb.r {
        60.0 * ((rgb.g - rgb.b) / d % 6.0)
    } else if max == rgb.g {
        60.0 * ((rgb.b - rgb.r) / d + 2.0)
    } else {
        60.0 * ((rgb.r - rgb.g) / d + 4.0)
    };
    if h < 0.0 {
        h += 360.0;
    }
    h
}

fn hue2rgb(p: f32, q: f32, t: f32) -> f32 {
    let mut t = t;
    if t < 0.0 {
        t += 1.0;
    }
    if t > 1.0 {
        t -= 1.0;
    }
    if t < 1.0 / 6.0 {
        return p + (q - p) * 6.0 * t;
    }
    if t < 1.0 / 2.0 {
        return q;
    }
    if t < 2.0 / 3.0 {
        return p + (q - p) * (2.0 / 3.0 - t) * 6.0;
    }
    p
}

impl ColorConverter {
    pub fn rgb_to_hsl(rgb: Rgb) -> Hsl {
        let max = rgb.r.max(rgb.g).max(rgb.b);
        let min = rgb.r.min(rgb.g).min(rgb.b);
        let l = (max + min) / 2.0;
        let mut h = 0.0f32;
        let mut s = 0.0f32;
        if max != min {
            let d = max - min;
            s = if l < 0.5 {
                d / (max + min)
            } else {
                d / (2.0 - max - min)
            };
            h = rgb_hue(rgb, max, d);
        }
        Hsl { h, s, l }
    }

    pub fn hsl_to_rgb(hsl: Hsl) -> Rgb {
        if hsl.s == 0.0 {
            return Rgb::new(hsl.l, hsl.l, hsl.l);
        }
        let q = if hsl.l < 0.5 {
            hsl.l * (1.0 + hsl.s)
        } else {
            hsl.l + hsl.s - hsl.l * hsl.s
        };
        let p = 2.0 * hsl.l - q;
        let hk = hsl.h / 360.0;
        let r = hue2rgb(p, q, hk + 1.0 / 3.0);
        let g = hue2rgb(p, q, hk);
        let b = hue2rgb(p, q, hk - 1.0 / 3.0);
        Rgb::new(r, g, b)
    }

    pub fn rgb_to_hsv(rgb: Rgb) -> Hsv {
        let max = rgb.r.max(rgb.g).max(rgb.b);
        let min = rgb.r.min(rgb.g).min(rgb.b);
        let d = max - min;
        let v = max;
        let s = if max == 0.0 { 0.0 } else { d / max };
        let h = if max == min { 0.0 } else { rgb_hue(rgb, max, d) };
        Hsv { h, s, v }
    }

    pub fn rgb_to_cmyk(rgb: Rgb) -> Cmyk {
        let max = rgb.r.max(rgb.g).max(rgb.b);
        let k = 1.0 - max;
        if k == 1.0 {
            return Cmyk {
                c: 0.0,
                m: 0.0,
                y: 0.0,
                k,
            };
        }
        let c = (1.0 - rgb.r - k) / (1.0 - k);
        let m = (1.0 - rgb.g - k) / (1.0 - k);
        let y = (1.0 - rgb.b - k) / (1.0 - k);
        Cmyk { c, m, y, k }
    }

    pub fn rgb_to_yuv(rgb: Rgb) -> Yuv {
        let y = 0.299 * rgb.r + 0.587 * rgb.g + 0.114 * rgb.b;
        let u = -0.147 * rgb.r + -0.289 * rgb.g + 0.436 * rgb.b;
        let v = 0.615 * rgb.r - 0.515 * rgb.g - 0.100 * rgb.b;
        Yuv { y, u, v }
    }

    pub fn adjust_brightness(rgb: Rgb, factor: f32) -> Rgb {
        Rgb::new(
            clamp01(rgb.r * factor),
            clamp01(rgb.g * factor),
            clamp01(rgb.b * factor),
        )
    }

    pub fn adjust_saturation(rgb: Rgb, factor: f32) -> Rgb {
        let mut hsl = Self::rgb_to_hsl(rgb);
        hsl.s = clamp01(hsl.s * factor);
        Self::hsl_to_rgb(hsl)
    }

    pub fn grayscale(rgb: Rgb) -> Rgb {
        let gray = 0.2126 * rgb.r + 0.7152 * rgb.g + 0.0722 * rgb.b;
        Rgb::new(gray, gray, gray)
    }

    pub fn invert(rgb: Rgb) -> Rgb {
        Rgb::new(1.0 - rgb.r, 1.0 - rgb.g, 1.0 - rgb.b)
    }

    pub fn color_distance(a: Rgb, b: Rgb) -> f32 {
        let dr = a.r - b.r;
        let dg = a.g - b.g;
        let db = a.b - b.b;
        (dr * dr + dg * dg + db * db).sqrt()
    }
}

//! C++ `std::cout << float` compatible formatting (printf "%.6g" semantics).

/// Format an f32 exactly like C++ iostream's default float formatting,
/// which is equivalent to printf("%.6g", value).
pub fn format_g(x: f32) -> String {
    if x.is_nan() {
        return if x.is_sign_negative() { "-nan".to_string() } else { "nan".to_string() };
    }
    if x.is_infinite() {
        return if x < 0.0 { "-inf".to_string() } else { "inf".to_string() };
    }
    if x == 0.0 {
        return if x.is_sign_negative() { "-0".to_string() } else { "0".to_string() };
    }

    // Round to 6 significant digits through scientific notation.
    let sci = format!("{:.5e}", x); // e.g. "-3.57628e-7"
    let epos = sci.find('e').unwrap();
    let mant = &sci[..epos];
    let exp: i32 = sci[epos + 1..].parse().unwrap();
    let neg = mant.starts_with('-');
    let digits: String = mant.chars().filter(|c| c.is_ascii_digit()).collect();
    debug_assert_eq!(digits.len(), 6);

    if exp < -4 || exp >= 6 {
        // Scientific notation: strip trailing zeros of the mantissa,
        // exponent has a sign and at least two digits.
        let mut out = String::new();
        if neg {
            out.push('-');
        }
        out.push(digits.as_bytes()[0] as char);
        let frac = digits[1..].trim_end_matches('0');
        if !frac.is_empty() {
            out.push('.');
            out.push_str(frac);
        }
        let sign = if exp < 0 { '-' } else { '+' };
        out.push('e');
        out.push(sign);
        let ae = exp.unsigned_abs();
        if ae < 10 {
            out.push('0');
        }
        out.push_str(&ae.to_string());
        out
    } else if exp >= 0 {
        // Fixed notation, exponent in [0, 5].
        let split = exp as usize + 1;
        let mut out = String::new();
        if neg {
            out.push('-');
        }
        out.push_str(&digits[..split]);
        let frac = digits[split..].trim_end_matches('0');
        if !frac.is_empty() {
            out.push('.');
            out.push_str(frac);
        }
        out
    } else {
        // Fixed notation, exponent in [-4, -1]: 0.00ddd
        let mut out = String::new();
        if neg {
            out.push('-');
        }
        out.push_str("0.");
        for _ in 0..(-exp - 1) {
            out.push('0');
        }
        let frac = digits.trim_end_matches('0');
        out.push_str(frac);
        out
    }
}

mod cfmt;
mod color;

use cfmt::format_g;
use color::{ColorConverter, Rgb};

/// Mimic C++ `std::stof`: skip leading whitespace, parse the longest valid
/// float prefix, ignore trailing garbage.
fn stof(s: &str) -> f32 {
    let trimmed = s.trim_start();
    let bytes = trimmed.as_bytes();
    let mut end = 0;

    let mut i = 0;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        i += 1;
    }
    // inf / nan (case-insensitive), like strtof.
    let lower = trimmed[i..].to_ascii_lowercase();
    if lower.starts_with("infinity") {
        end = i + 8;
    } else if lower.starts_with("inf") || lower.starts_with("nan") {
        end = i + 3;
    } else {
        let mut saw_digit = false;
        while i < bytes.len() && bytes[i].is_ascii_digit() {
            i += 1;
            saw_digit = true;
        }
        if i < bytes.len() && bytes[i] == b'.' {
            i += 1;
            while i < bytes.len() && bytes[i].is_ascii_digit() {
                i += 1;
                saw_digit = true;
            }
        }
        if saw_digit {
            end = i;
            // optional exponent
            if i < bytes.len() && (bytes[i] == b'e' || bytes[i] == b'E') {
                let mut j = i + 1;
                if j < bytes.len() && (bytes[j] == b'+' || bytes[j] == b'-') {
                    j += 1;
                }
                let exp_start = j;
                while j < bytes.len() && bytes[j].is_ascii_digit() {
                    j += 1;
                }
                if j > exp_start {
                    end = j;
                }
            }
        } else {
            // std::stof throws std::invalid_argument; abort like the C++ binary.
            std::process::abort();
        }
    }

    trimmed[..end].parse::<f32>().unwrap_or_else(|_| std::process::abort())
}

fn push_val(out: &mut String, v: f32) {
    out.push_str(&format_g(v));
    out.push(' ');
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut colors: Vec<Rgb> = Vec::new();
    colors.push(Rgb::new(0.1, 0.2, 0.3));
    colors.push(Rgb::new(0.4, 0.5, 0.6));
    colors.push(Rgb::new(0.7, 0.2, 0.1));
    colors.push(Rgb::new(0.3, 0.8, 0.4));
    colors.push(Rgb::new(0.9, 0.1, 0.8));

    let argc = args.len();
    let mut i = 1;
    while i + 2 < argc {
        let r = stof(&args[i]);
        let g = stof(&args[i + 1]);
        let b = stof(&args[i + 2]);
        colors.push(Rgb::new(r, g, b));
        i += 3;
    }

    let mut out = String::new();
    for i in 0..colors.len() {
        let rgb = colors[i];

        let hsl = ColorConverter::rgb_to_hsl(rgb);
        let hsv = ColorConverter::rgb_to_hsv(rgb);
        let cmyk = ColorConverter::rgb_to_cmyk(rgb);
        let yuv = ColorConverter::rgb_to_yuv(rgb);

        let bright = ColorConverter::adjust_brightness(rgb, 1.2);
        let dark = ColorConverter::adjust_brightness(rgb, 0.8);

        let saturated = ColorConverter::adjust_saturation(rgb, 1.5);

        let gray = ColorConverter::grayscale(rgb);

        let inverted = ColorConverter::invert(rgb);

        out.push_str(&format!("Color {}: ", i));
        push_val(&mut out, rgb.r);
        push_val(&mut out, rgb.g);
        push_val(&mut out, rgb.b);
        push_val(&mut out, hsl.h);
        push_val(&mut out, hsl.s);
        push_val(&mut out, hsl.l);
        push_val(&mut out, hsv.h);
        push_val(&mut out, hsv.s);
        push_val(&mut out, hsv.v);
        push_val(&mut out, cmyk.c);
        push_val(&mut out, cmyk.m);
        push_val(&mut out, cmyk.y);
        push_val(&mut out, cmyk.k);
        push_val(&mut out, yuv.y);
        push_val(&mut out, yuv.u);
        push_val(&mut out, yuv.v);
        push_val(&mut out, bright.r);
        push_val(&mut out, bright.g);
        push_val(&mut out, bright.b);
        push_val(&mut out, dark.r);
        push_val(&mut out, dark.g);
        push_val(&mut out, dark.b);
        push_val(&mut out, saturated.r);
        push_val(&mut out, saturated.g);
        push_val(&mut out, saturated.b);
        push_val(&mut out, gray.r);
        push_val(&mut out, gray.g);
        push_val(&mut out, gray.b);
        push_val(&mut out, inverted.r);
        push_val(&mut out, inverted.g);
        push_val(&mut out, inverted.b);

        if i == colors.len() - 1 && colors.len() > 1 {
            let dist = ColorConverter::color_distance(rgb, colors[0]);
            push_val(&mut out, dist);
        }

        out.push('\n');
    }

    print!("{}", out);
}

