// Brute-force hue formula + saturation expression variants against C++ corpus.
use std::fs;

fn fmt_g(x: f32) -> String {
    if x == 0.0 {
        return if x.is_sign_negative() { "-0".into() } else { "0".into() };
    }
    let sci = format!("{:.5e}", x);
    let epos = sci.find('e').unwrap();
