// variant id -> hue
fn hue(rgb:[f32;3], max:f32, d:f32, v:u32) -> f32 {
    let (a, o6, o360): (f32,f32,f32) = if max == rgb[0] { (rgb[1]-rgb[2], 0.0, 0.0) }
        else if max == rgb[1] { (rgb[2]-rgb[0], 2.0, 120.0) }
        else { (rgb[0]-rgb[1], 4.0, 240.0) };
    let isr = max == rgb[0];
    match v {
        0 => { let mut h = if isr { 60.0*(a/d % 6.0) } else { 60.0*(a/d + o6) }; if h<0.0 {h+=360.0;} h }
        1 => { let mut h = a/d*60.0 + o360; if h<0.0 {h+=360.0;} h }
        2 => { let mut x = a/d; if isr && x<0.0 {x+=6.0;} if !isr {x+=o6;} x*60.0 }
        3 => { let mut h = (a*60.0)/d + o360; if h<0.0 {h+=360.0;} h }
        4 => { let mut h = a*(60.0/d) + o360; if h<0.0 {h+=360.0;} h }
        5 => { let mut h = a/(d/60.0) + o360; if h<0.0 {h+=360.0;} h }
        6 => { // all double
            let ad = a as f64; let dd = d as f64;
            let mut h = if isr { 60.0*(ad/dd % 6.0) } else { 60.0*(ad/dd + o6 as f64) };
            if h<0.0 {h+=360.0;}
            h as f32 }
        7 => { // double ratio, float mul/add
            let r = ((a as f64)/(d as f64)) as f32;
            let mut h = if isr { 60.0*(r % 6.0) } else { 60.0*(r + o6) };
            if h<0.0 {h+=360.0;} h }
        8 => { // float ratio, double mul/add
            let r = a/d;
            let mut h = if isr { 60.0f64*((r % 6.0) as f64) } else { 60.0f64*((r + o6) as f64) };
            if h<0.0 {h+=360.0;}
            h as f32 }
        9 => { let mut h = 60.0*a/d + o360; if h<0.0 {h+=360.0;} h } // (60*a)/d
        10 => { let mut h = a/d*60.0; if isr && h<0.0 {h+=360.0;} h += o360; h } // add off after correction
        _ => 0.0,
    }
}
fn main() {
    let corpus = fs::read_to_string("/tmp/corpus.tsv").unwrap();
    let mut cases: Vec<([f32;3], String)> = Vec::new();
